import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#game'), mapCanvas=document.querySelector('#map'), mapCtx=mapCanvas.getContext('2d');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x86c8b3); scene.fog=new THREE.Fog(0x86c8b3,65,155);
const camera=new THREE.PerspectiveCamera(62,innerWidth/innerHeight,.1,240);
const renderer=new THREE.WebGLRenderer({canvas,antialias:false,powerPreference:'low-power'}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.5)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=false; renderer.outputColorSpace=THREE.SRGBColorSpace;
scene.add(new THREE.HemisphereLight(0xc7f6eb,0x59744b,2.1));const sun=new THREE.DirectionalLight(0xffedc4,2.5);sun.position.set(-35,70,25);scene.add(sun);
const mat=(color,roughness=1)=>new THREE.MeshStandardMaterial({color,roughness,flatShading:true});
const mats={sand:mat(0xc7bd82),grass:mat(0x6d9c68),darkGrass:mat(0x4f805f),water:mat(0x55a9a9),wood:mat(0x9b6946),roof:mat(0x935e48),cream:mat(0xe4d8ac),blue:mat(0x4c8790),metal:mat(0x728a8a),leaf:mat(0x377b60),leaf2:mat(0x5a9a68),trunk:mat(0x705238),rock:mat(0x8e9c88),yellow:mat(0xd9ff65),red:mat(0xe66a4d),white:mat(0xe9e9d4),skin:mat(0xd89a6d),pants:mat(0x354c4b),enemy:mat(0xc76c4c),enemy2:mat(0x4a587c)};
function mesh(geo,material,parent=scene){const m=new THREE.Mesh(geo,material);parent.add(m);return m}
function box(parent,x,y,z,w,h,d,material){const m=mesh(new THREE.BoxGeometry(w,h,d),material,parent);m.position.set(x,y,z);return m}
function cylinder(parent,x,y,z,rt,rb,h,material,sides=7){const m=mesh(new THREE.CylinderGeometry(rt,rb,h,sides),material,parent);m.position.set(x,y,z);return m}
function sphere(parent,x,y,z,r,material,detail=0){const m=mesh(new THREE.IcosahedronGeometry(r,detail),material,parent);m.position.set(x,y,z);return m}
// Island and low-poly shoreline
const water=mesh(new THREE.PlaneGeometry(400,400),mats.water);water.rotation.x=-Math.PI/2;water.position.y=-1.35;
const ground=mesh(new THREE.CircleGeometry(78,48),mats.grass);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;
const beach=mesh(new THREE.CircleGeometry(80,48),mats.sand);beach.rotation.x=-Math.PI/2;beach.position.y=-.32;
const lowland=mesh(new THREE.CircleGeometry(73,48),mats.grass);lowland.rotation.x=-Math.PI/2;lowland.position.y=-.08;
// Terrain bumps, tiny islands/pebbled accents
for(let i=0;i<35;i++){let x=(Math.random()-.5)*140,z=(Math.random()-.5)*140;if(x*x+z*z>67*67)continue;let hill=sphere(scene,x,-1.0,z,1+Math.random()*2.2,i%3?mats.darkGrass:mats.grass,1);hill.scale.set(1.7,.3,1.3)}
// buildings
const buildings=[];
function house(x,z,w,d,wall= mats.cream, roof=mats.roof){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);box(g,0,1.35,0,w,2.7,d,wall);box(g,0,2.85,0,w+.3,.24,d+.3,roof);const door=box(g,0,.8,d/2+.015,.85,1.6,.06,mats.wood);box(g,-w*.25,1.75,d/2+.025,.62,.56,.05,mats.blue);box(g,w*.25,1.75,d/2+.025,.62,.56,.05,mats.blue);buildings.push({x,z,r:Math.max(w,d)*.58});return g}
house(-20,-20,11,9);house(18,-23,10,8,mats.blue,mats.cream);house(30,8,12,9,mats.cream,mats.blue);house(-32,15,9,10,mats.blue,mats.roof);house(3,29,12,9,mats.cream,mats.roof);
// containers and barricades
for(const [x,z,c] of [[-7,-30,0x426e73],[8,-13,0xa34b3f],[26,-4,0x486b7a],[-20,4,0xa34b3f],[9,9,0x557c70],[-39,-13,0x486b7a]]){const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);const m=mat(c);box(g,0,1,0,7,2,2.6,m);for(let t=-2.7;t<3;t+=.9)box(g,t,1,1.33,.06,1.8,.05,mats.metal);}
for(let i=0;i<11;i++){const a=i/11*Math.PI*2;const x=Math.cos(a)*38,z=Math.sin(a)*38;box(scene,x,.55,z,Math.random()*4+2,1.1,.55,mats.wood).rotation.y=a}
// palms, shrubs and rocks
const obstacles=[];
function palm(x,z,s=1){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);cylinder(g,0,2.1,0,.22*s,.38*s,4.2*s,mats.trunk,6);for(let i=0;i<6;i++){const a=i*Math.PI/3;const leaf=mesh(new THREE.ConeGeometry(.42*s,3.8*s,4),i%2?mats.leaf:mats.leaf2,g);leaf.position.set(Math.sin(a)*1.25*s,4.05*s,Math.cos(a)*1.25*s);leaf.rotation.z=Math.cos(a)*.9;leaf.rotation.x=Math.sin(a)*.9;leaf.rotation.y=a}obstacles.push({x,z,r:.55*s})}
for(let i=0;i<38;i++){const a=Math.random()*Math.PI*2,r=14+Math.random()*51,x=Math.cos(a)*r,z=Math.sin(a)*r;if(buildings.some(b=>Math.hypot(x-b.x,z-b.z)<b.r+4))continue;palm(x,z,.65+Math.random()*.55)}
for(let i=0;i<27;i++){let x=(Math.random()-.5)*120,z=(Math.random()-.5)*120;if(x*x+z*z>66*66)continue;const rock=sphere(scene,x,.45,z,.8+Math.random()*1.1,mats.rock,0);rock.scale.set(1.3,.75,1);obstacles.push({x,z,r:1.2})}
// simple crate props
for(let i=0;i<14;i++){let x=(Math.random()-.5)*70,z=(Math.random()-.5)*70;if(x*x+z*z>55*55)continue;box(scene,x,.55,z,1.1,1.1,1.1,mats.wood);box(scene,x,.58,z,.13,1.15,1.14,mats.roof)}
// playable actor models
function makeActor(color,isPlayer=false){const g=new THREE.Group();scene.add(g);const bodyMat=color;const torso=mesh(new THREE.CapsuleGeometry(.43,.62,3,6),bodyMat,g);torso.position.y=1.35;const head=sphere(g,0,2.15,0,.34,mats.skin,1);const pack=box(g,0,1.45,-.46,.65,.72,.28,mat(0x596956));const legs=[];for(const dx of [-.22,.22]){const leg=mesh(new THREE.CapsuleGeometry(.18,.58,2,5),mats.pants,g);leg.position.set(dx,.53,0);legs.push(leg)}const gun=box(g,.43,1.45,-.05,.78,.13,.17,mat(0x273333));g.userData={torso,head,legs,gun,baseY:0};return g}
const player={group:makeActor(mat(0x457a72),true),hp:100,alive:true,yaw:0,pitch:-.08,speed:8,weapon:'rifle',ammo:{rifle:30,shotgun:6,pistol:12},reserve:{rifle:120,shotgun:24,pistol:60},medkits:2,crouch:false,ads:false,shootCooldown:0,reload:0,jumpY:0,jumpV:0,drop:0};
player.group.position.set(1,0,8);
// Parachute canopy during drop
const canopy=new THREE.Group();scene.add(canopy);const canopyTop=mesh(new THREE.SphereGeometry(3,8,5,0,Math.PI*2,0,Math.PI/2),mat(0xe3edcf));canopyTop.position.y=0;canopy.add(canopyTop);for(let i=0;i<5;i++){const cord=mesh(new THREE.CylinderGeometry(.018,.018,2,4),mats.white,canopy);cord.position.set((i-2)*.75,-1,0)}canopy.visible=false;
// Loot items
const loot=[];const lootDefs=[['rifle','M4A1 RIFLE',0xd9ff65],['shotgun','12G SHOTGUN',0xff936a],['pistol','SIDEARM',0x80e4db],['ammo','AMMO +30',0xf3db76],['medkit','MEDKIT',0xf2f1e7]];
const lootSpots=[[-16,-19,'rifle'],[-23,-17,'ammo'],[18,-19,'shotgun'],[21,-24,'medkit'],[28,10,'pistol'],[-29,17,'ammo'],[4,26,'rifle'],[8,32,'medkit'],[-5,-2,'shotgun'],[13,3,'ammo'],[-37,-12,'medkit'],[0,-39,'pistol'],[35,-8,'ammo'],[-13,14,'rifle'],[18,28,'shotgun']];
function spawnLoot(x,z,type){const color=lootDefs.find(d=>d[0]===type)?.[2]||0xffffff;const g=new THREE.Group();scene.add(g);g.position.set(x,.35,z);const core=mesh(new THREE.OctahedronGeometry(.38,0),mat(color),g);core.position.y=.35;const ring=mesh(new THREE.TorusGeometry(.55,.055,5,12),mat(color),g);ring.rotation.x=Math.PI/2;ring.position.y=.08;loot.push({x,z,type,group:g,core,ring,active:true});}
lootSpots.forEach(([x,z,t])=>spawnLoot(x,z,t));
// Bot squad
const bots=[];const botNames=['Rook','Vex','Mako','Nyx','Kite'];const spawnPoints=[[-42,-35],[42,-31],[41,35],[-41,37],[0,-49]];
spawnPoints.forEach((p,i)=>{const group=makeActor(i%2?mats.enemy:mats.enemy2);group.position.set(p[0],0,p[1]);bots.push({group,hp:100,alive:true,name:botNames[i],think:Math.random()*2,shoot:2+Math.random()*3,phase:Math.random()*6})});
const bullets=[];const tracers=[];let active=false,paused=false,gameEnded=false,dropDone=false,elapsed=0,zoneStart=80,zoneEnd=330,zoneRadius=70,zoneCenter={x:0,z:0},safeRadius=70,toastTimeout=0,fireHeld=false,keys={},joy={x:0,y:0,active:false},last=performance.now(),lootTarget=null;
// luminous safe-zone ring
const zoneRing=mesh(new THREE.TorusGeometry(1,.16,6,100),new THREE.MeshBasicMaterial({color:0xb5ff70,transparent:true,opacity:.8}));zoneRing.rotation.x=Math.PI/2;zoneRing.position.y=.12;
// UI refs
const $=s=>document.querySelector(s), mapSize=148;
function toast(text){const e=$('#lootToast');e.textContent=text;e.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>e.classList.remove('show'),1500)}
function setWeapon(w){if(!player.ammo[w]&&player.reserve[w]<=0){toast('NO AMMO — FIND MORE');return}player.weapon=w;document.querySelectorAll('.weapon-switch button').forEach(b=>b.classList.toggle('active',b.dataset.weapon===w));const data={rifle:['PRIMARY WEAPON','M4A1 · ASSAULT RIFLE'],shotgun:['CLOSE QUARTERS','M1887 · SHOTGUN'],pistol:['SIDEARM','G18 · PISTOL']}[w];$('#weaponType').textContent=data[0];$('#weaponName').textContent=data[1];updateHud()}
function updateHud(){const w=player.weapon;$('#ammoNow').textContent=player.ammo[w];$('#ammoReserve').textContent=player.reserve[w];$('#healthNum').textContent=Math.ceil(player.hp);$('#healthBar').style.width=Math.max(0,player.hp)+'%';$('#medCount').textContent=player.medkits;$('#aliveCount').textContent=String(bots.filter(b=>b.alive).length+1).padStart(2,'0')}
function damagePlayer(n){if(!player.alive)return;player.hp=Math.max(0,player.hp-n);$('#damageflash').classList.remove('on');void $('#damageflash').offsetWidth;$('#damageflash').classList.add('on');updateHud();if(player.hp<=0)endGame(false)}
function endGame(win){if(gameEnded)return;gameEnded=true;active=false;$('#overlay').classList.remove('hidden');$('#overlay .eyebrow').textContent=win?'ISLAND CHAMPION':'MATCH COMPLETE';$('#overlay h1').innerHTML=win?'BOOYA<span style="color:#d9ff65">H!</span><br><em>VICTORY</em>':'GAME<br><em>OVER</em>';$('#overlay p').textContent=win?'You own North Cove. Every rival has been eliminated. Queue up and do it again.':'The island got the better of you this time. Regroup, drop back in, and claim your victory.';$('#startBtn').textContent='RESTART MATCH  →';$('#overlay .panel>p:last-child').style.display='none'}
function resetGame(){player.hp=100;player.alive=true;player.yaw=0;player.pitch=-.08;player.weapon='rifle';player.ammo={rifle:30,shotgun:6,pistol:12};player.reserve={rifle:120,shotgun:24,pistol:60};player.medkits=2;player.crouch=false;player.ads=false;player.drop=0;player.group.position.set(1,0,8);bots.forEach((b,i)=>{b.hp=100;b.alive=true;b.group.visible=true;b.group.position.set(...spawnPoints[i],0);b.think=1;b.shoot=3+Math.random()*2});loot.forEach(l=>{l.active=true;l.group.visible=true});elapsed=0;safeRadius=70;gameEnded=false;dropDone=false;paused=false;active=true;$('#overlay').classList.add('hidden');$('#overlay .panel>p:last-child').style.display='block';$('#centerMessage').style.display='none';$('#dropUI').style.display='block';canopy.visible=true;setWeapon('rifle');updateHud()}

// Input: keyboard, mouse-look, virtual stick, and touch action buttons
function bindHold(id,down,up=()=>{}){const el=$(id);el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture?.(e.pointerId);down()});for(const ev of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(ev,e=>{e.preventDefault();up()})}
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyR')reload();if(e.code==='Space')jump();if(e.code==='KeyC')toggleCrouch();if(e.code==='KeyQ')useMed();if(e.code==='Digit1')setWeapon('rifle');if(e.code==='Digit2')setWeapon('shotgun');if(e.code==='Digit3')setWeapon('pistol')});window.addEventListener('keyup',e=>keys[e.code]=false);
let lookPointer=null,lastPX=0,lastPY=0;
canvas.addEventListener('pointerdown',e=>{if(!active||e.target!==canvas)return;lookPointer=e.pointerId;lastPX=e.clientX;lastPY=e.clientY;canvas.setPointerCapture(e.pointerId)});
canvas.addEventListener('pointermove',e=>{if(lookPointer!==e.pointerId||!active)return;const dx=e.clientX-lastPX,dy=e.clientY-lastPY;lastPX=e.clientX;lastPY=e.clientY;player.yaw-=dx*.006;player.pitch=THREE.MathUtils.clamp(player.pitch-dy*.003,-.42,.25)});
for(const ev of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,e=>{if(lookPointer===e.pointerId)lookPointer=null});
const joyEl=$('#joystick'),knob=$('#joyknob');let joyPointer=null;
joyEl.addEventListener('pointerdown',e=>{e.preventDefault();joyPointer=e.pointerId;joyEl.setPointerCapture(e.pointerId);joy.active=true;moveJoy(e)});joyEl.addEventListener('pointermove',e=>{if(joyPointer===e.pointerId)moveJoy(e)});function endJoy(e){if(joyPointer!==e.pointerId)return;joyPointer=null;joy.active=false;joy.x=joy.y=0;knob.style.transform='translate(-50%,-50%)'}joyEl.addEventListener('pointerup',endJoy);joyEl.addEventListener('pointercancel',endJoy);
function moveJoy(e){const r=joyEl.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=r.width*.34,d=Math.hypot(dx,dy),s=Math.min(1,max/d);joy.x=dx*s/max;joy.y=dy*s/max;knob.style.transform=`translate(calc(-50% + ${joy.x*max}px),calc(-50% + ${joy.y*max}px))`}
bindHold('#fireBtn',()=>fireHeld=true,()=>fireHeld=false);bindHold('#jumpBtn',jump);bindHold('#crouchBtn',toggleCrouch);bindHold('#adsBtn',()=>{player.ads=!player.ads;$('#adsBtn').classList.toggle('active',player.ads);camera.fov=player.ads?45:62;camera.updateProjectionMatrix()});bindHold('#medBtn',useMed);$('#pauseBtn').onclick=()=>{if(!active)return;paused=!paused;$('#pauseBtn').textContent=paused?'▶':'Ⅱ';toast(paused?'MATCH PAUSED':'MATCH RESUMED')};$('#soundBtn').onclick=()=>{$('#soundBtn').classList.toggle('sound-off');toast($('#soundBtn').classList.contains('sound-off')?'SOUND OFF':'SOUND ON')};$('#startBtn').onclick=resetGame;document.querySelectorAll('.weapon-switch button').forEach(b=>b.onclick=()=>setWeapon(b.dataset.weapon));
function toggleCrouch(){player.crouch=!player.crouch;$('#crouchBtn').classList.toggle('active',player.crouch)}
function jump(){if(!active||!dropDone||player.jumpY>0)return;player.jumpV=8.5}
function reload(){if(!active||player.reload>0)return;const w=player.weapon,capacity={rifle:30,shotgun:6,pistol:12}[w],need=capacity-player.ammo[w];if(need<=0||player.reserve[w]<=0){toast('MAGAZINE FULL');return}player.reload=w==='shotgun'?1.5:1.15;toast('RELOADING…')}
function useMed(){if(!active||player.medkits<=0||player.hp>=100)return;player.medkits--;player.hp=Math.min(100,player.hp+38);toast('MEDKIT USED  +38 HP');updateHud()}
function shoot(){if(!active||!dropDone||player.reload>0)return;const w=player.weapon;if(player.ammo[w]<=0){reload();return}const rate={rifle:.16,shotgun:.62,pistol:.3}[w];if(player.shootCooldown>0)return;player.shootCooldown=rate;player.ammo[w]--;updateHud();const forward=new THREE.Vector3(-Math.sin(player.yaw),0,-Math.cos(player.yaw));forward.applyAxisAngle(new THREE.Vector3(0,1,0),player.ads?0:(Math.random()-.5)*.045);let target=null,best=Infinity;const range={rifle:58,shotgun:22,pistol:38}[w];for(const b of bots){if(!b.alive)continue;const to=new THREE.Vector3(b.group.position.x-player.group.position.x,0,b.group.position.z-player.group.position.z);const dist=to.length();if(dist>range)continue;to.normalize();const dot=forward.dot(to);if(dot>(w==='shotgun'?.93:.975)&&dist<best){best=dist;target=b}}if(target){const dmg={rifle:35,shotgun:58,pistol:25}[w]*(1-Math.max(0,best-10)*.008);target.hp-=dmg;target.group.userData.torso.material=mat(0xffb0a1);setTimeout(()=>{if(target.alive)target.group.userData.torso.material=target===bots[1]||target===bots[3]?mats.enemy:mats.enemy2},90);$('#hitmarker').classList.remove('show');void $('#hitmarker').offsetWidth;$('#hitmarker').classList.add('show');if(target.hp<=0){target.alive=false;target.group.visible=false;toast(`${target.name.toUpperCase()} ELIMINATED`);updateHud();if(bots.every(b=>!b.alive))endGame(true)}}}
// Simple collision against large cover objects
function collides(x,z){for(const b of buildings)if(Math.abs(x-b.x)<b.r&&Math.abs(z-b.z)<b.r*.75)return true;for(const o of obstacles)if(Math.hypot(x-o.x,z-o.z)<o.r+.55)return true;return false}
function movePlayer(dt){let sx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+(joy.active?joy.x:0);let sy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+(joy.active?joy.y:0);const len=Math.hypot(sx,sy);if(len>1){sx/=len;sy/=len}const speed=player.speed*(player.crouch?.48:1)*(player.ads?.76:1);const fwd=new THREE.Vector3(-Math.sin(player.yaw),0,-Math.cos(player.yaw));const right=new THREE.Vector3(Math.cos(player.yaw),0,-Math.sin(player.yaw));const dx=(right.x*sx+fwd.x*(-sy))*speed*dt,dz=(right.z*sx+fwd.z*(-sy))*speed*dt;const p=player.group.position;if(!collides(p.x+dx,p.z))p.x+=dx;if(!collides(p.x,p.z+dz))p.z+=dz;p.x=THREE.MathUtils.clamp(p.x,-75,75);p.z=THREE.MathUtils.clamp(p.z,-75,75);player.group.rotation.y=player.yaw;player.group.position.y=player.jumpY;player.group.userData.legs.forEach((l,i)=>{l.rotation.x=len>.1?Math.sin(elapsed*12+i*Math.PI)*.65:0})}
function updateBots(dt){for(const b of bots){if(!b.alive)continue;const p=b.group.position,dx=player.group.position.x-p.x,dz=player.group.position.z-p.z,dist=Math.hypot(dx,dz);b.phase+=dt;b.think-=dt;b.shoot-=dt;b.group.rotation.y=Math.atan2(-dx,-dz);if(dist<43&&dropDone){if(dist>11){const speed=2.2;let nx=p.x+dx/dist*speed*dt,nz=p.z+dz/dist*speed*dt;if(!collides(nx,nz)){p.x=nx;p.z=nz}b.group.userData.legs.forEach((l,i)=>l.rotation.x=Math.sin(elapsed*7+i*Math.PI)*.45)}else{p.x+=Math.sin(b.phase*1.1)*dt*1.5;p.z+=Math.cos(b.phase*.9)*dt*1.5}if(dist<34&&b.shoot<=0){b.shoot=2.1+Math.random()*1.5;if(Math.random()<.58)damagePlayer(5+Math.random()*5)}}else if(b.think<=0){b.think=2+Math.random()*2;const a=Math.random()*Math.PI*2,r=15+Math.random()*32;b.group.userData.goal={x:Math.cos(a)*r,z:Math.sin(a)*r}}if(b.think>0&&dist>=43&&b.group.userData.goal){const g=b.group.userData.goal,gx=g.x-p.x,gz=g.z-p.z,gd=Math.hypot(gx,gz);if(gd>1){p.x+=gx/gd*1.5*dt;p.z+=gz/gd*1.5*dt}}if(Math.hypot(p.x-zoneCenter.x,p.z-zoneCenter.z)>safeRadius)b.hp-=dt*2.2;if(b.hp<=0){b.alive=false;b.group.visible=false;updateHud()}}}
function updateLoot(dt){lootTarget=null;for(const l of loot){if(!l.active)continue;l.core.rotation.y+=dt*1.3;l.group.position.y=.35+Math.sin(elapsed*2.2+l.x)*.09;const d=Math.hypot(l.x-player.group.position.x,l.z-player.group.position.z);if(d<2.8){lootTarget=l;break}}if(lootTarget){$('#lootNear').classList.add('show');$('#lootHint').classList.add('show');$('#lootHint').textContent=`${lootTarget.type.toUpperCase()}  ·  WALK OVER TO PICK UP`}else{$('#lootNear').classList.remove('show');$('#lootHint').classList.remove('show')}if(lootTarget&&Math.hypot(lootTarget.x-player.group.position.x,lootTarget.z-player.group.position.z)<1.55){const t=lootTarget.type;lootTarget.active=false;lootTarget.group.visible=false;if(t==='ammo'){player.reserve.rifle+=30;player.reserve.shotgun+=6;player.reserve.pistol+=12;toast('AMMO PICKED UP  +30')}else if(t==='medkit'){player.medkits++;toast('MEDKIT PICKED UP')}else{player.ammo[t]+=t==='shotgun'?6:t==='pistol'?12:30;player.reserve[t]+=t==='shotgun'?12:t==='pistol'?24:60;setWeapon(t);toast(`${t.toUpperCase()} PICKED UP`)}updateHud()}}
