import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/node_modules/playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox', '--enable-unsafe-swiftshader'] });
const page = await browser.newPage();
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.route('**/game.js', async route => {
  const response = await route.fetch();
  const source = await response.text();
  await route.fulfill({ response, body: source + '\nwindow.__test = { player, bots, resetGame, updateZone, damagePlayer, shoot, endGame, get state(){return {active, paused, gameEnded, dropDone, elapsed, safeRadius};} };' });
});
await page.goto('http://localhost:3002');
await page.waitForFunction(() => !!window.__test);
await page.locator('#startBtn').click();
await page.waitForFunction(() => window.__test.state.dropDone);

const zone = await page.evaluate(async () => {
  const t = window.__test;
  t.player.hp = 100;
  t.player.group.position.set(74, 0, 0);
  t.updateZone(1);
  return { hp: t.player.hp, warning: document.querySelector('#zoneWarn').classList.contains('show') };
});
if (!(zone.hp < 100 && zone.warning)) throw new Error(`Safe-zone test failed: ${JSON.stringify(zone)}`);

await page.evaluate(() => {
  const t = window.__test;
  t.resetGame();
  t.player.group.position.set(0, 0, 0);
  t.player.yaw = 0;
  for (const b of t.bots) { b.alive = false; b.group.visible = false; }
  const last = t.bots[0];
  last.alive = true;
  last.group.visible = true;
  last.hp = 1;
  last.group.position.set(0, 0, -5);
  t.player.ammo.rifle = 30;
  t.shoot();
});
const victory = await page.locator('#overlay').evaluate(el => ({ visible: !el.classList.contains('hidden'), title: el.querySelector('h1').innerText }));
if (!victory.visible || !victory.title.includes('VICTORY')) throw new Error(`Victory test failed: ${JSON.stringify(victory)}`);

await page.locator('#startBtn').click();
await page.evaluate(() => window.__test.damagePlayer(200));
const loss = await page.locator('#overlay').evaluate(el => ({ visible: !el.classList.contains('hidden'), title: el.querySelector('h1').innerText }));
if (!loss.visible || !loss.title.includes('OVER')) throw new Error(`Game-over test failed: ${JSON.stringify(loss)}`);

await page.locator('#startBtn').click();
const restart = await page.evaluate(() => ({ hp: window.__test.player.hp, ammo: window.__test.player.ammo.rifle, active: window.__test.state.active, overlayHidden: document.querySelector('#overlay').classList.contains('hidden') }));
if (restart.hp !== 100 || restart.ammo !== 30 || !restart.active || !restart.overlayHidden) throw new Error(`Restart test failed: ${JSON.stringify(restart)}`);
if (errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`);
console.log(JSON.stringify({ zone, victory, loss, restart, pageErrors: errors }, null, 2));
await browser.close();

